// Entire private pool wrapper/core/split/free/unlink graph; caller supplies valid pool backing/list topology.
namespace Recovered.Gameplay
{
 public static class RecoveredScriptPrivatePool
 {
  //27-byte register-entry helper; second next/previous read remains live after the first store.
  public static void Unlink(TakeoverReleaseMemory m,uint block){uint previous=m.Read32(block+8);if(previous!=0)m.Write32(previous+4,m.Read32(block+4));uint next=m.Read32(block+4);if(next!=0)m.Write32(next+8,m.Read32(block+8));}
  //177-byte split: allocates at the tail of the chosen free block and adjusts size for aligned user pointer.
  public static void Split(TakeoverReleaseMemory m,uint block,ref uint size,uint alignment,out uint allocated,out uint remainder){unchecked{uint remaining=(m.Read32(block)&0x7fffffff)-size-16;remainder=block;allocated=block+remaining+16;if(alignment!=0){uint user=allocated+12,rounded=(user+alignment-1)&~(alignment-1),shift=rounded-user;allocated+=shift;size-=shift;remaining+=shift;}m.Write32(allocated,m.Read32(allocated)|0x80000000);m.Write32(allocated,(m.Read32(allocated)&0x80000000)|size);m.Write32(allocated+4,0);m.Write32(allocated+8,0);m.Write32(allocated+(m.Read32(allocated)&0x7fffffff)+12,allocated);m.Write32(remainder,m.Read32(remainder)&0x7fffffff);m.Write32(remainder,(m.Read32(remainder)&0x80000000)|remaining);m.Write32(remainder+4,0);m.Write32(remainder+8,0);m.Write32(remainder+(m.Read32(remainder)&0x7fffffff)+12,remainder);}}
  //26-byte public wrapper supplies reserved0;179-byte core searches with STRICT size>request+alignment+16.
  public static uint Allocate(TakeoverReleaseMemory m,uint pool,uint size,uint alignment){return Core(m,pool,size,alignment,0);}
  public static uint Core(TakeoverReleaseMemory m,uint pool,uint size,uint alignment,uint reserved){unchecked{uint root=m.Read32(pool)+16;if(size==0)return 0;size+=alignment;uint needed=size+16,block=root;while(block!=0){if((m.Read32(block)&0x7fffffff)>needed)break;block=m.Read32(block+4);}if(block==0)return 0;Unlink(m,block);uint allocated,remainder;Split(m,block,ref size,alignment,out allocated,out remainder);uint head=m.Read32(root+4);if(head!=0)m.Write32(head+8,remainder);m.Write32(remainder+4,m.Read32(root+4));m.Write32(remainder+8,root);m.Write32(root+4,remainder);m.Write32(pool+8,m.Read32(pool+8)+1);m.Write32(pool+12,m.Read32(pool+12)+(m.Read32(allocated)&0x7fffffff)+16);return allocated+12;}}
  //227-byte release: inclusive range check; caller's in-range pointer must identify a prepared allocation.
  public static void Free(TakeoverReleaseMemory m,uint pool,uint pointer){unchecked{uint poolBase=m.Read32(pool),root=poolBase+16;if(pointer==0||pointer<poolBase||pointer>poolBase+m.Read32(pool+4))return;uint block=pointer-12;m.Write32(block,m.Read32(block)&0x7fffffff);m.Write32(pool+8,m.Read32(pool+8)-1);uint size=m.Read32(block)&0x7fffffff;m.Write32(pool+12,m.Read32(pool+12)-size-16);uint head=m.Read32(root+4);if(head!=0)m.Write32(head+8,block);m.Write32(block+8,root);m.Write32(block+4,m.Read32(root+4));m.Write32(root+4,block);uint next=block+(m.Read32(block)&0x7fffffff)+16;if((m.Read32(next)&0x80000000)==0){Unlink(m,next);size=(m.Read32(next)&0x7fffffff)+(m.Read32(block)&0x7fffffff)+16;m.Write32(block,(m.Read32(block)&0x80000000)|size);m.Write32(block+(m.Read32(block)&0x7fffffff)+12,block);}uint previous=m.Read32(block-4);if((m.Read32(previous)&0x80000000)==0){Unlink(m,block);size=(m.Read32(block)&0x7fffffff)+(m.Read32(previous)&0x7fffffff)+16;m.Write32(previous,(m.Read32(previous)&0x80000000)|size);m.Write32(previous+(m.Read32(previous)&0x7fffffff)+12,previous);}}}
 }
}
